import 'package:flutter/material.dart';
import '../main.dart';
import '../models/smart_basket.dart';
class BasketScreen extends StatelessWidget { const BasketScreen({super.key, required this.controller}); final FavourController controller; @override Widget build(BuildContext context) { final result = SmartBasketCalculator.calculate(controller.data.basket, controller.data.offers); return ListView(padding: const EdgeInsets.all(20), children: [Text('Smart Basket', style: Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight: FontWeight.bold)), const Text('Uses latest available offers and known recorded fees.'), const SizedBox(height: 16), if (controller.data.basket.isEmpty) const Center(child: Padding(padding: EdgeInsets.all(36), child: Text('Add products from comparisons to calculate your basket.'))), ...controller.data.basket.map((item) => Card(child: ListTile(title: Text(item.product.displayName), subtitle: Text('${item.quantity} × ${item.product.packLabel}'), trailing: IconButton(icon: const Icon(Icons.remove_circle_outline), onPressed: () => controller.save(controller.data.copyWith(basket: controller.data.basket.where((entry) => entry.product.id != item.product.id).toList()))))), if (controller.data.basket.isNotEmpty) const SizedBox(height: 16), if (!result.complete && controller.data.basket.isNotEmpty) const Card(child: Padding(padding: EdgeInsets.all(16), child: Text('Insufficient price data: record at least one available price for every item.'))), if (result.complete) _Plan(result: result)]); } }
class _Plan extends StatelessWidget { const _Plan({required this.result}); final SmartBasketResult result; @override Widget build(BuildContext context) => Card(color: Theme.of(context).colorScheme.primaryContainer, child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('Best split basket: ₹${result.split!.total.toStringAsFixed(2)}', style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.bold)), ...result.split!.allocations.map((allocation) => Text('${allocation.item.product.displayName}: ${allocation.offer.retailer.name}')), const SizedBox(height: 10), if (result.single != null) Text('Best complete retailer: ${result.single!.retailer!.name} — ₹${result.single!.total.toStringAsFixed(2)}'), if (result.single != null) Text(result.splitWins ? 'Splitting saves ₹${result.savings.toStringAsFixed(2)}.' : 'One retailer is cheaper by ₹${result.savings.toStringAsFixed(2)}.'), const SizedBox(height: 6), const Text('Totals include item prices and only explicitly recorded fees.', style: TextStyle(fontSize: 12))])); }
